export class Product {
  brandName: string;
  name: string;
  price: string;
  imageLink: string;
  detailLink: string;
  description: string;
  
  constructor(
    brandName: string = '',
    name: string = '',
    price: string = '',
    imageLink: string = '',
    detailLink: string = '',
    description: string = ''
  ) {
    this.brandName = brandName;
    this.name = name;
    this.price = price;
    this.imageLink = imageLink;
    this.detailLink = detailLink;
    this.description = description;
  }
}

// Interface matching the exact API response
export interface ProductApiResponse {
  code: number;
  message: string;
  data: Product[];
}
